# Check horizontal axis of symmetry (reflection across vertical midline)
def is_row_mirror(grid):
    h = len(grid)
    w = len(grid[0])
    # Check if each row is a palindrome
    for row in grid:
        if row != row[::-1]:
            return False
    return True

print("Is each row a palindrome?", is_row_mirror(grid))

# Check for vertical axis of symmetry (left-right reflection)
# This would mean column i == column (w-1-i)
def has_vertical_symmetry(grid):
    h = len(grid)
    w = len(grid[0])
    for r in range(h):
        for c in range(w // 2):
            if grid[r][c] != grid[r][w - 1 - c]:
                return False
    return True

print("Has vertical symmetry?", has_vertical_symmetry(grid))

# Check for horizontal axis of symmetry (top-bottom reflection)
def has_horizontal_symmetry(grid):
    h = len(grid)
    for r in range(h // 2):
        if grid[r] != grid[h - 1 - r]:
            return False
    return True

print("Has horizontal symmetry?", has_horizontal_symmetry(grid))

# What about rotation by 180 degrees?
def has_180_rotation(grid):
    h = len(grid)
    w = len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] != grid[h - 1 - r][w - 1 - c]:
                return False
    return True

print("Has 180-degree rotation symmetry?", has_180_rotation(grid))

# Let's print unique values and their counts
from collections import Counter
all_cells = [cell for row in grid for cell in row]
print("\nValue distribution:", dict(Counter(all_cells)))
